import numpy as np, itertools, math
cams = [
 ((3.559,-6.1649,2.5165),(-0.4851,0.8403,-0.2419),(-0.1209,0.2095,0.9703)),
 ((9.3792,0.0,4.1553),(-0.9397,0.0,-0.342),(-0.342,0.0,0.9397)),
 ((3.8437,6.6581,2.6585),(-0.4851,-0.8403,-0.2419),(-0.1209,-0.2095,0.9703)),
 ((-3.7225,6.4482,3.4516),(0.4698,-0.8138,-0.342),(0.171,-0.2962,0.9397)),
 ((-8.303,0.0,2.8118),(0.9703,0.0,-0.2419),(0.2419,0.0,0.9703)),
 ((-5.0644,-8.7726,4.4285),(0.4698,0.8138,-0.342),(0.171,0.2962,0.9397)),
]
def frame(c,l,u):
    L=np.array(l,float); U=np.array(u,float); L/=np.linalg.norm(L); U/=np.linalg.norm(U)
    R=np.cross(L,U); R/=np.linalg.norm(R); return np.array(c,float),L,R,U
FR=[frame(*c) for c in cams]
def proj(P,F):
    C,L,R,U=F; v=np.array(P,float)-C
    zc=v@L
    if zc<=0.05: return None
    return 384+(v@R)/zc*1067, 384-(v@U)/zc*1067
def bbox(pts):
    xs=[p[0] for p in pts if p]; ys=[p[1] for p in pts if p]
    return min(xs),max(xs),min(ys),max(ys)
def dresser_corners(cx,cy,yaw,L,D,H):
    ct,st=math.cos(yaw),math.sin(yaw)
    pts=[]
    for lz in (0.0,H):
        for a,b in ((L/2,D/2),(-L/2,D/2),(-L/2,-D/2),(L/2,-D/2)):
            pts.append((cx+a*ct-b*st, cy+a*st+b*ct, lz))
    return pts
# ref bboxes (768px): view: (x0,x1,y0,y1)
REF_A = {0:(428,551,333,405), 1:(596,671,366,485), 4:(37,135,376,505), 5:(217,341,321,399)}
# weights: v1 full, v5 full, v4 full, v0: px + ytop only (occluded bottom)
def loss_A(cx,cy,yaw,L,D,H):
    pts=[proj(p,FR[v]) for v in (0,1,4,5) for p in dresser_corners(cx,cy,yaw,L,D,H)]
    tot=0.0
    i=0
    for v in (0,1,4,5):
        bb=bbox(pts[i*8:(i+1)*8]); i+=1
        rx0,rx1,ry0,ry1=REF_A[v]
        e=(bb[0]-rx0)**2+(bb[1]-rx1)**2
        if v!=0: e+=(bb[2]-ry0)**2+(bb[3]-ry1)**2
        else: e+=(bb[2]-ry0)**2   # top only for v0
        tot+=e
    return tot
best=None
for cx in np.arange(-0.9,0.85,0.15):
  for cy in np.arange(1.6,3.5,0.15):
    for yawd in range(0,45,5):
      for L in (0.9,1.05,1.2,1.35,1.5,1.7):
        for H in (0.95,1.05,1.15):
          l=loss_A(cx,cy,math.radians(yawd),L,0.45,H)
          if best is None or l<best[0]: best=(l,cx,cy,yawd,L,H)
print("BEST A:", best)
l,cx,cy,yawd,L,H=best
for v in (0,1,4,5):
    bb=bbox([proj(p,FR[v]) for p in dresser_corners(cx,cy,math.radians(yawd),L,0.45,H)])
    print(f"  v{v}: pred {bb[0]:.0f}-{bb[1]:.0f} / {bb[2]:.0f}-{bb[3]:.0f}  ref {REF_A[v]}")
